<script setup>
import { onMounted, ref } from 'vue'
import { supabase } from '../lib/supabase'
const users=ref([]),loading=ref(true),error=ref(''),notice=ref(''),savingId=ref(null)
async function load(){loading.value=true;const {data,error:e}=await supabase.from('profiles').select('id,full_name,email,role,created_at').order('created_at',{ascending:false});if(e)error.value=e.message;else users.value=data||[];loading.value=false}
async function saveRole(user){error.value='';notice.value='';savingId.value=user.id;const {error:e}=await supabase.from('profiles').update({role:user.role}).eq('id',user.id);if(e)error.value=e.message;else notice.value='User role updated.';savingId.value=null}
onMounted(load)
</script>
<template><div><p class="text-[10px] font-bold uppercase tracking-[.18em] text-[#a17c20]">Super admin settings</p><h1 class="mt-2 font-display text-3xl font-extrabold">Users</h1><p class="mt-2 text-sm text-slate-500">Manage CMS access and assign user roles.</p><div v-if="error" class="mt-5 rounded-lg bg-red-50 p-3 text-xs text-red-700">{{error}}</div><div v-if="notice" class="mt-5 rounded-lg bg-green-50 p-3 text-xs text-green-700">{{notice}}</div><div class="mt-7 overflow-hidden rounded-xl border border-[#e8edf3] bg-white"><div class="border-b border-slate-100 p-5"><h2 class="font-display text-base font-bold">CMS users</h2><p class="mt-1 text-xs text-slate-500">Only Super Admin can access this page and update roles.</p></div><div v-if="loading" class="p-8 text-center text-xs text-slate-500">Loading users…</div><div v-else-if="!users.length" class="p-8 text-center text-xs text-slate-500">No user profiles found.</div><div v-else class="overflow-x-auto"><table class="w-full min-w-[680px] text-left text-xs"><thead class="bg-slate-50 text-[9px] uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-3">User</th><th class="px-5 py-3">Email</th><th class="px-5 py-3">Role</th><th class="px-5 py-3">Action</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="user in users" :key="user.id"><td class="px-5 py-4 font-semibold">{{user.full_name||'Unnamed user'}}</td><td class="px-5 py-4 text-slate-500">{{user.email||'—'}}</td><td class="px-5 py-4"><select v-model="user.role" class="rounded-md border border-slate-200 bg-white px-3 py-2 text-xs"><option value="owner">Super Admin</option><option value="admin">Admin</option><option value="editor">Editor</option></select></td><td class="px-5 py-4"><button @click="saveRole(user)" :disabled="savingId===user.id" class="rounded-md bg-[#092f70] px-3 py-2 text-[10px] font-bold text-white disabled:opacity-50">{{savingId===user.id?'Saving…':'Save role'}}</button></td></tr></tbody></table></div></div></div></template>